// Parse LinkedIn comment notification emails into structured records.
// The Gmail node (simple=false) already provides: text, subject, from, messageId, date.
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const j = item.json || {};
  const subject = j.subject || '';
  const from = typeof j.from === 'string' ? j.from : JSON.stringify(j.from || '');
  if (!/linkedin\.com/i.test(from)) continue;

  // English + German subject patterns. Extend for other languages.
  const m = subject.match(/^(.*?)\s+(commented on your post|hat (?:Ihren|deinen) Beitrag kommentiert|replied to your comment|hat auf (?:Ihren|deinen) Kommentar geantwortet)/i);
  if (!m) continue;
  const name = m[1].trim();

  const text = j.text || '';
  const paras = text.split(/\r?\n\s*\r?\n/).map(p => p.trim()).filter(Boolean);
  // paras[0] = headline (same as subject), then the comment (quoted), then the post preview.
  let comment = '';
  const postParts = [];
  for (let i = 1; i < paras.length; i++) {
    const p = paras[i];
    if (/^(Anzeigen|Mitdiskutieren|View |Join the|Diese E-Mail|This email)/.test(p)) break;
    if (!comment) { comment = p.replace(/^[\u201E\u201C"']+|[\u201C\u201D"']+$/g, '').trim(); continue; }
    postParts.push(p);
  }
  const postTitle = postParts.join(' ').replace(/\s+/g, ' ').slice(0, 200);

  const urlMatch = text.match(/(https:\/\/www\.linkedin\.com\/(?:comm\/)?feed\/update\/\S+)/);
  const postUrl = urlMatch ? urlMatch[1] : null;

  const msgId = j.messageId || j.id || null;
  if (!msgId || seen.has(msgId)) continue;
  seen.add(msgId);

  let receivedAt = null;
  if (j.date) { const d = new Date(j.date); if (!isNaN(d)) receivedAt = d.toISOString(); }

  out.push({ json: {
    commenter_name: name,
    comment_text: comment || '',
    post_title: postTitle || '',
    post_url: postUrl || '',
    mail_message_id: msgId,
    received_at: receivedAt || '',
  }});
}
return out;

// Input: the rows already logged in the Google Sheet (may be empty).
// Keep only parsed comments whose Gmail message id is not in the sheet yet.
const logged = new Set(
  $input.all().map(r => String((r.json || {}).mail_message_id || '')).filter(Boolean)
);
const fresh = [];
for (const item of $('Parse Comment Details').all()) {
  const id = String(item.json.mail_message_id || '');
  if (!id || logged.has(id)) continue;
  fresh.push({ json: item.json });
}
return fresh;

